const stats = $('Parse Today Stats').first().json;
const quotaRaw = ($input.first().json.stdout || '').trim();
let hunter = null;
try {
  const parsed = quotaRaw ? JSON.parse(quotaRaw) : null;
  hunter = parsed && parsed.hunter ? parsed.hunter : parsed;
} catch {}
return [{ json: { ...stats, hunter } }];

const statsRes = JSON.parse($('Query Week Stats').first().json.stdout || '{}');
const row = (statsRes.rows && statsRes.rows[0]) || {};
const totals = row.totals || {};
const sources = row.sources || [];
const companies = row.top_companies || [];

const jobsRes = JSON.parse($input.first().json.stdout || '{}');
const jobs = jobsRes.rows || [];

const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const num = (n) => Number(n ?? 0).toLocaleString();
const pct = (n) => `${Number(n ?? 0)}%`;
const tierColor = (t) => t === 1 ? '#9fe88f' : t === 2 ? '#ffb86b' : '#888';

const weekStart = new Date(Date.now() - 7*24*60*60*1000).toISOString().slice(0,10);
const weekEnd = new Date().toISOString().slice(0,10);

const sourceRows = sources.length ? sources.map(s => `<tr>
  <td style="padding:10px 12px;border-bottom:1px solid #2a2a2a;font-weight:600;color:#fff">${esc(s.source_board)}</td>
  <td style="padding:10px 12px;border-bottom:1px solid #2a2a2a;text-align:right;color:#fff">${num(s.total_jobs)}</td>
  <td style="padding:10px 12px;border-bottom:1px solid #2a2a2a;text-align:right;color:#9fe88f">${num(s.tier1_jobs)}</td>
  <td style="padding:10px 12px;border-bottom:1px solid #2a2a2a;text-align:right;color:#9ec5ff">${num(s.email_sent)}</td>
  <td style="padding:10px 12px;border-bottom:1px solid #2a2a2a;text-align:right;color:#ffb86b">${num(s.easy_apply)}</td>
  <td style="padding:10px 12px;border-bottom:1px solid #2a2a2a;text-align:right;color:#bbb">${num(s.manual)}</td>
  <td style="padding:10px 12px;border-bottom:1px solid #2a2a2a;text-align:right;color:#fff">${pct(s.response_rate)}</td>
</tr>`).join('') : `<tr><td colspan="7" style="padding:14px;color:#888;text-align:center">No applications in the last 7 days.</td></tr>`;

const companyChips = companies.length
  ? companies.map(c => `<span style="display:inline-block;background:#2a2a2a;color:#eee;padding:6px 10px;border-radius:14px;margin:3px;font-size:13px">${esc(c.company)} <span style="color:#888">×${c.n}</span></span>`).join('')
  : '<span style="color:#888">No companies yet</span>';

const jobCard = (j) => {
  const tier = j.ai_priority_tier ?? 0;
  const tags = (j.tech_stack || []).slice(0, 6).map(t => `<span style="display:inline-block;background:#1f1f1f;color:#9ec5ff;padding:3px 8px;border-radius:10px;margin:2px;font-size:11px">${esc(t)}</span>`).join('');
  const meta = [j.industry, j.hq_location, j.location].filter(Boolean).map(esc).join(' • ');
  const contact = j.hiring_manager_email
    ? `<div style="margin-top:6px;color:#9fe88f;font-size:13px">✉ ${j.hiring_manager_name ? esc(j.hiring_manager_name) + ' — ' : ''}<a href="mailto:${esc(j.hiring_manager_email)}" style="color:#9fe88f;text-decoration:none">${esc(j.hiring_manager_email)}</a></div>`
    : '';
  const links = [
    j.website ? `<a href="${esc(j.website)}" style="color:#9ec5ff;text-decoration:none;margin-right:10px">🌐 site</a>` : '',
    j.company_linkedin ? `<a href="${esc(j.company_linkedin)}" style="color:#9ec5ff;text-decoration:none;margin-right:10px">💼 linkedin</a>` : '',
    j.github ? `<a href="${esc(j.github)}" style="color:#9ec5ff;text-decoration:none;margin-right:10px">🐙 github</a>` : '',
    j.job_url ? `<a href="${esc(j.job_url)}" style="color:#9ec5ff;text-decoration:none;margin-right:10px">📄 job</a>` : '',
  ].filter(Boolean).join('');
  return `<div style="background:#141414;border:1px solid #2a2a2a;border-radius:10px;padding:14px;margin-bottom:10px">
    <div style="display:flex;justify-content:space-between;gap:10px;align-items:start">
      <div style="flex:1">
        <div style="font-weight:700;color:#fff;font-size:15px">${esc(j.job_title)} <span style="color:#888;font-weight:400">— ${esc(j.company)}</span></div>
        ${meta ? `<div style="color:#888;font-size:12px;margin-top:3px">${meta}</div>` : ''}
      </div>
      <div style="text-align:right;white-space:nowrap">
        <span style="background:${tierColor(tier)};color:#000;padding:2px 8px;border-radius:8px;font-size:11px;font-weight:700">T${tier || '-'}</span>
        <span style="color:#888;font-size:12px;margin-left:6px">${j.ai_job_match_score ?? '-'}/100</span>
      </div>
    </div>
    ${j.one_liner ? `<div style="color:#ccc;font-size:13px;margin-top:8px">${esc(j.one_liner)}</div>` : ''}
    ${tags ? `<div style="margin-top:8px">${tags}</div>` : ''}
    <div style="color:#888;font-size:12px;margin-top:8px">${esc(j.application_method)} • ${esc(j.status || '')} • ${esc(j.source_board)}</div>
    ${contact}
    ${links ? `<div style="margin-top:6px;font-size:13px">${links}</div>` : ''}
  </div>`;
};

const t1 = jobs.filter(j => j.ai_priority_tier === 1);
const t2 = jobs.filter(j => j.ai_priority_tier === 2);
const other = jobs.filter(j => j.ai_priority_tier !== 1 && j.ai_priority_tier !== 2);
const jobsSection = jobs.length
  ? [
      t1.length ? `<h3 style="color:#9fe88f;font-size:14px;margin:16px 0 8px">Tier 1 — ${t1.length}</h3>${t1.map(jobCard).join('')}` : '',
      t2.length ? `<h3 style="color:#ffb86b;font-size:14px;margin:16px 0 8px">Tier 2 — ${t2.length}</h3>${t2.map(jobCard).join('')}` : '',
      other.length ? `<h3 style="color:#888;font-size:14px;margin:16px 0 8px">Untagged — ${other.length}</h3>${other.map(jobCard).join('')}` : '',
    ].join('')
  : '<div style="color:#888;text-align:center;padding:14px">No jobs this week.</div>';

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>jHound Weekly Digest</title></head>
<body style="margin:0;padding:0;background:#0e0e0e;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#eee">
  <div style="max-width:720px;margin:0 auto;padding:28px 22px">
    <h1 style="margin:0 0 4px;font-size:24px;color:#fff">🎯 jHound Weekly Digest</h1>
    <div style="color:#888;font-size:13px;margin-bottom:24px">${weekStart} → ${weekEnd}</div>

    <div style="display:flex;flex-wrap:wrap;gap:10px;margin-bottom:24px">
      <div style="flex:1;min-width:130px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:10px;padding:14px"><div style="color:#888;font-size:11px;text-transform:uppercase">Total</div><div style="font-size:26px;font-weight:700;color:#fff">${num(totals.total)}</div></div>
      <div style="flex:1;min-width:130px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:10px;padding:14px"><div style="color:#888;font-size:11px;text-transform:uppercase">Tier 1</div><div style="font-size:26px;font-weight:700;color:#9fe88f">${num(totals.tier1)}</div></div>
      <div style="flex:1;min-width:130px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:10px;padding:14px"><div style="color:#888;font-size:11px;text-transform:uppercase">Email Sent</div><div style="font-size:26px;font-weight:700;color:#9ec5ff">${num(totals.email_sent)}</div></div>
      <div style="flex:1;min-width:130px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:10px;padding:14px"><div style="color:#888;font-size:11px;text-transform:uppercase">Easy Apply</div><div style="font-size:26px;font-weight:700;color:#ffb86b">${num(totals.easy_apply)}</div></div>
      <div style="flex:1;min-width:130px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:10px;padding:14px"><div style="color:#888;font-size:11px;text-transform:uppercase">Responses</div><div style="font-size:26px;font-weight:700;color:#fff">${num(totals.responses)}</div></div>
    </div>

    <h2 style="font-size:16px;color:#fff;margin:24px 0 10px">Jobs This Week (${jobs.length})</h2>
    ${jobsSection}

    <h2 style="font-size:16px;color:#fff;margin:24px 0 10px">Sources</h2>
    <table cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;background:#141414;border:1px solid #2a2a2a;border-radius:10px;overflow:hidden">
      <thead><tr style="background:#1a1a1a">
        <th style="text-align:left;padding:10px 12px;font-size:12px;color:#888">Board</th>
        <th style="text-align:right;padding:10px 12px;font-size:12px;color:#888">Total</th>
        <th style="text-align:right;padding:10px 12px;font-size:12px;color:#888">Tier 1</th>
        <th style="text-align:right;padding:10px 12px;font-size:12px;color:#888">Email</th>
        <th style="text-align:right;padding:10px 12px;font-size:12px;color:#888">EasyApp</th>
        <th style="text-align:right;padding:10px 12px;font-size:12px;color:#888">Manual</th>
        <th style="text-align:right;padding:10px 12px;font-size:12px;color:#888">Resp %</th>
      </tr></thead>
      <tbody>${sourceRows}</tbody>
    </table>

    <h2 style="font-size:16px;color:#fff;margin:24px 0 10px">Top Companies</h2>
    <div style="background:#141414;border:1px solid #2a2a2a;border-radius:10px;padding:10px">${companyChips}</div>

    <div style="color:#666;font-size:11px;margin-top:28px;text-align:center">jHound · automated job hunter</div>
  </div>
</body></html>`;

const plain = [
  `jHound Weekly Digest (${weekStart} → ${weekEnd})`,
  '',
  `Total: ${totals.total ?? 0} | Tier1: ${totals.tier1 ?? 0} | Email: ${totals.email_sent ?? 0} | EasyApply: ${totals.easy_apply ?? 0} | Manual: ${totals.manual ?? 0} | Responses: ${totals.responses ?? 0}`,
  '',
  `Jobs this week (${jobs.length}):`,
  ...jobs.map(j => `  - [T${j.ai_priority_tier ?? '-'}] ${j.job_title} — ${j.company} (${j.application_method}) ${j.hiring_manager_email ? '<' + j.hiring_manager_email + '> ' : ''}${j.website || j.job_url}`),
  '',
  'Sources:',
  ...sources.map(s => `  - ${s.source_board}: ${s.total_jobs} (T1:${s.tier1_jobs}, email:${s.email_sent}, easy:${s.easy_apply}, manual:${s.manual}, resp:${s.response_rate}%)`),
  '',
  'Top companies:',
  ...companies.map(c => `  - ${c.company} × ${c.n}`),
].join('\n');

return [{ json: { to: $env.USER_EMAIL, subject: `jHound Weekly Digest — ${weekEnd}`, body: plain, html, skip_attachments: true } }];
